def query(name, qtype=1, server='127.0.0.11'):
    tid=0xabcd
    hdr=struct.pack('>HHHHHH', tid, 0x0100, 1,0,0,0)
    qn=b''.join(bytes([len(x)])+x.encode() for x in name.split('.'))+b'\x00'
