import socket, struct

def build_query(name, qtype, qclass=1, rd=True, tid=0x1234):
    flags = 0x0100 if rd else 0
    hdr = struct.pack('>HHHHHH', tid, flags, 1, 0, 0, 0)
    qn = b''.join(bytes([len(x)]) + x.encode() for x in name.split('.')) + b'\x00'
    return hdr + qn + struct.pack('>HH', qtype, qclass)

def parse(data):
    tid, flags, qd, an, ns, ar = struct.unpack('>HHHHHH', data[:12])
    print(f"  rcode={flags & 0xF} an={an} ns={ns} ar={ar}")
    i = 12
    # skip question
    while data[i] != 0:
        i += 1 + data[i] if False else 0
        i += data[i] + 1 - (data[i]+1)  # noop
        break
    # safer: re-walk
    i = 12
    while data[i] != 0:
        i += data[i] + 1
    i += 5  # null + qtype + qclass
    def skip_name(i):
        while True:
            b = data[i]
            if b & 0xC0 == 0xC0:
                return i + 2
            if b == 0:
                return i + 1
            i += b + 1
    for section, count in [("answer", an), ("authority", ns), ("additional", ar)]:
        for _ in range(count):
            i = skip_name(i)
            rtype, rclass, ttl, rdlen = struct.unpack('>HHIH', data[i:i+10]); i += 10
            rdata = data[i:i+rdlen]; i += rdlen
            if rtype == 1:
                print(f"  [{section}] A -> {'.'.join(map(str,rdata))}")
            elif rtype == 5:
                print(f"  [{section}] CNAME len={rdlen}")
            elif rtype == 2:
                # NS
                j = 0; labels=[]
                while rdata[j] != 0 and j < len(rdata):
                    if rdata[j] & 0xC0 == 0xC0: break
                    l = rdata[j]; labels.append(rdata[j+1:j+1+l].decode('utf-8','replace')); j += 1+l
                print(f"  [{section}] NS -> {'.'.join(labels)}")
            else:
                print(f"  [{section}] type={rtype} rdata={rdata[:40]}")

for name, qt, qdesc in [("prices.internal", 255, "ANY"), ("prices.internal", 2, "NS"), ("internal", 2, "NS"), ("internal", 6, "SOA")]:
    print(f"== {name} {qdesc}")
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(3)
    try:
        s.sendto(build_query(name, qt), ('127.0.0.11', 53))
        data, _ = s.recvfrom(4096)
        parse(data)
    except Exception as e:
        print("  ERR", e)
    finally:
        s.close()
EOF"}

